package com.thingsbook.library;
import android.content.Context;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.zip.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** Fixed-model pack installation. Private states/catalog stay Keystore encrypted. */
final class PersonalVoicePack {
 static final int MAX_STATE=16*1024*1024;static final long MAX_PACK=400L*1024*1024;
 static final String MODEL_HASH="fb0dc01b0d4d2e1c905b7a3e0676e3d9c96d5ae460e24e3ab94981805babf997";
 static final Map<String,String> HASHES=new HashMap<>();static{HASHES.put("models/model.safetensors",MODEL_HASH);HASHES.put("models/config.yaml","1dd65925aef5b494f5937e8c04a4218493c8283a1a02fe0045f4af28cf37b53d");HASHES.put("models/tokenizer.json","f498428e1eafee50492f7be13dc9bfafcfc12e508cd0eb1b01c92ecd5d8c6687");}
 interface Guard{void check()throws Exception;}
 interface KeySource{SecretKey key(boolean create)throws Exception;}
 private final KeySource testKey;private final File files;private final AtomicFile pointer;
 PersonalVoicePack(Context c){this(c.getFilesDir(),null);}
 PersonalVoicePack(File root,KeySource source){files=root;testKey=source;pointer=new AtomicFile(new File(files,"personal-voices-active"));}
 static String hex(byte[] value){StringBuilder b=new StringBuilder();for(byte n:value)b.append(String.format(Locale.ROOT,"%02x",n&255));return b.toString();}
 static String sha(byte[] bytes)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(bytes));}
 static String fileKey(String id)throws Exception{return sha(id.getBytes(StandardCharsets.UTF_8))+".enc";}
 private SecretKey key(boolean create)throws Exception{if(testKey!=null)return testKey.key(create);KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);String alias="ThingsBook.personal-voices.v1";if(s.containsAlias(alias))return(SecretKey)s.getKey(alias,null);if(!create)throw new IOException("Personal voice key unavailable.");KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).setRandomizedEncryptionRequired(true).build());return g.generateKey();}
 private void seal(File target,byte[] plain)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(true));byte[] bytes=c.doFinal(plain);try(FileOutputStream out=new FileOutputStream(target)){out.write(c.getIV());out.write(bytes);out.getFD().sync();}finally{Arrays.fill(bytes,(byte)0);}}
 private byte[] open(File target)throws Exception{if(target.length()<28||target.length()>MAX_STATE+28)throw new IOException("Invalid private voice size.");byte[] packed=read(new FileInputStream(target),MAX_STATE+28,null);try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,Arrays.copyOf(packed,12)));return c.doFinal(packed,12,packed.length-12);}finally{Arrays.fill(packed,(byte)0);}}
 static byte[] read(InputStream in,int max,Guard guard)throws Exception{try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[32768];try{int n;while((n=in.read(buffer))!=-1){if(guard!=null)guard.check();if(out.size()+n>max)throw new IOException("Voice pack entry exceeds its limit.");out.write(buffer,0,n);}return out.toByteArray();}finally{Arrays.fill(buffer,(byte)0);}}finally{if(!(in instanceof ZipInputStream))in.close();}}
 static void validateState(byte[] bytes)throws Exception{if(bytes.length<16||bytes.length>MAX_STATE)throw new IOException("Invalid voice state size.");ByteBuffer data=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);long length=data.getLong();if(length<2||length>1048576||length>bytes.length-8)throw new IOException("Invalid voice tensor header.");JSONObject header=new JSONObject(new String(bytes,8,(int)length,StandardCharsets.UTF_8));ArrayList<long[]> ranges=new ArrayList<>();int count=0;for(Iterator<String> it=header.keys();it.hasNext();){String name=it.next();if(name.equals("__metadata__"))continue;if(!name.matches("transformer\\.layers\\.[0-5]\\.self_attn/(cache|offset|pad)"))throw new IOException("Unsupported voice tensor.");JSONObject t=header.getJSONObject(name);JSONArray shape=t.getJSONArray("shape"),offsets=t.getJSONArray("data_offsets");long size=1;boolean cache=name.endsWith("/cache");if(cache){if(!"F32".equals(t.getString("dtype"))||shape.length()!=5||shape.getLong(0)!=2||shape.getLong(1)!=1||shape.getLong(2)<1||shape.getLong(2)>512||shape.getLong(3)!=16||shape.getLong(4)!=64)throw new IOException("Unsupported voice cache shape.");for(int j=0;j<5;j++)size*=shape.getLong(j);size*=4;}else{if(!"I64".equals(t.getString("dtype"))||shape.length()!=1||shape.getLong(0)!=1)throw new IOException("Unsupported voice offset.");size=8;}if(offsets.length()!=2)throw new IOException("Invalid tensor offsets.");long begin=offsets.getLong(0),end=offsets.getLong(1),start=8+length;if(begin<0||end<begin||end-begin!=size||end>bytes.length-start)throw new IOException("Invalid tensor bounds.");ranges.add(new long[]{begin,end});if(cache){for(long n=begin;n<end;n+=4){float v=data.getFloat((int)(start+n));if(!Float.isFinite(v)||Math.abs(v)>1000000)throw new IOException("Invalid voice cache values.");}}else{long v=data.getLong((int)(start+begin));if(v<0||v>4096)throw new IOException("Invalid voice position.");}count++;}if(count!=18)throw new IOException("Expected six complete voice layers.");ranges.sort(Comparator.comparingLong(a->a[0]));long position=0;for(long[] r:ranges){if(r[0]!=position)throw new IOException("Overlapping or incomplete voice tensors.");position=r[1];}if(position!=bytes.length-8-length)throw new IOException("Trailing voice state data.");}
 private File active()throws Exception{byte[] raw;try{raw=pointer.readFully();}catch(FileNotFoundException missing){return null;}if(raw.length>128)throw new IOException("Invalid voice pack pointer.");String name=new String(raw,StandardCharsets.UTF_8);if(!name.matches("personal-pack-[a-f0-9-]{36}"))throw new IOException("Invalid voice pack pointer.");File folder=new File(files,name);if(!folder.isDirectory())throw new IOException("Installed voice pack unavailable.");return folder;}
 synchronized JSONObject catalog()throws Exception{File folder=active();if(folder==null)return new JSONObject().put("voices",new JSONArray());byte[] raw=open(new File(folder,"catalog.enc"));try{return new JSONObject(new String(raw,StandardCharsets.UTF_8));}finally{Arrays.fill(raw,(byte)0);}}
 synchronized String modelDirectory()throws Exception{File f=active();if(f==null)throw new IOException("Install your private voice pack first.");return new File(f,"models").getCanonicalPath();}
 synchronized void verifyModels(Guard guard)throws Exception{File folder=active();if(folder==null)throw new IOException("Private voices are not installed.");for(Map.Entry<String,String> expected:HASHES.entrySet()){guard.check();MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(new File(folder,expected.getKey()))){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){guard.check();digest.update(buffer,0,n);}}if(!hex(digest.digest()).equals(expected.getValue()))throw new IOException("Voice model verification failed. Reinstall the private pack.");}}
 synchronized byte[] state(String id)throws Exception{if(id==null||!id.matches("[a-z][a-z0-9-]{0,63}"))throw new IOException("Invalid voice.");JSONObject catalog=catalog();JSONArray voices=catalog.getJSONArray("voices");JSONObject entry=null;for(int i=0;i<voices.length();i++)if(id.equals(voices.getJSONObject(i).optString("id")))entry=voices.getJSONObject(i);if(entry==null)throw new IOException("This personal voice is not installed.");byte[] raw=open(new File(active(),fileKey(id)));try{if(!sha(raw).equals(entry.getString("sha256")))throw new IOException("Private voice verification failed.");validateState(raw);return raw;}catch(Exception e){Arrays.fill(raw,(byte)0);throw e;}}
 synchronized int install(InputStream source,Guard guard)throws Exception{File stage=new File(files,"personal-pack-"+UUID.randomUUID().toString());if(!stage.mkdir())throw new IOException("Cannot create voice installation folder.");boolean committed=false;try(ZipInputStream zip=new ZipInputStream(source)){
  ZipEntry first=zip.getNextEntry();if(first==null||!first.getName().equals("manifest.json"))throw new IOException("Choose the ThingsBook private Android voice pack.");byte[] manifestBytes=read(zip,65536,guard);JSONObject manifest=new JSONObject(new String(manifestBytes,StandardCharsets.UTF_8));Arrays.fill(manifestBytes,(byte)0);if(manifest.optInt("version")!=1||!manifest.optString("model_sha256").equals(MODEL_HASH))throw new IOException("This voice model is not supported.");JSONObject expected=manifest.getJSONObject("files");ZipEntry second=zip.getNextEntry();if(second==null||!second.getName().equals("catalog.json"))throw new IOException("Missing voice catalog.");byte[] catalogBytes=read(zip,65536,guard);JSONObject catalog;try{if(!sha(catalogBytes).equals(expected.getJSONObject("catalog.json").getString("sha256")))throw new IOException("Voice catalog integrity failure.");catalog=new JSONObject(new String(catalogBytes,StandardCharsets.UTF_8));}finally{Arrays.fill(catalogBytes,(byte)0);}JSONArray voices=catalog.getJSONArray("voices");if(voices.length()<1||voices.length()>30)throw new IOException("Unsupported voice count.");Map<String,JSONObject> voicePaths=new HashMap<>();for(int i=0;i<voices.length();i++){JSONObject voice=voices.getJSONObject(i);String id=voice.getString("id"),name=voice.getString("name");if(!id.matches("[a-z][a-z0-9-]{0,63}")||name.isEmpty()||name.length()>120||voicePaths.put("voices/"+id+".safetensors",voice)!=null)throw new IOException("Invalid or duplicate voice profile.");}
  if(expected.length()!=HASHES.size()+voicePaths.size()+1)throw new IOException("Unexpected voice pack entries.");Set<String> seen=new HashSet<>();seen.add("catalog.json");long total=0;ZipEntry e;while((e=zip.getNextEntry())!=null){guard.check();String name=e.getName();if(e.isDirectory()||!seen.add(name)||(!HASHES.containsKey(name)&&!voicePaths.containsKey(name)))throw new IOException("Unexpected, duplicate or unsafe pack entry.");JSONObject meta=expected.getJSONObject(name);long size=meta.getLong("bytes");if(size<1||size>250000000||(total+=size)>MAX_PACK)throw new IOException("Voice pack exceeds storage limits.");String hash=meta.getString("sha256");MessageDigest digest=MessageDigest.getInstance("SHA-256");if(HASHES.containsKey(name)){File dest=new File(stage,name);dest.getParentFile().mkdirs();long count=0;try(OutputStream out=new FileOutputStream(dest)){byte[] b=new byte[65536];int n;while((n=zip.read(b))!=-1){guard.check();count+=n;if(count>size)throw new IOException("Pack entry exceeds expected size.");digest.update(b,0,n);out.write(b,0,n);}}String actual=hex(digest.digest());if(count!=size||!actual.equals(hash)||!actual.equals(HASHES.get(name)))throw new IOException("Pinned model verification failed.");}else{byte[] raw=read(zip,MAX_STATE,guard);try{if(raw.length!=size||!sha(raw).equals(hash))throw new IOException("Voice state integrity failure.");validateState(raw);JSONObject voice=voicePaths.get(name);voice.put("sha256",hash);seal(new File(stage,fileKey(voice.getString("id"))),raw);}finally{Arrays.fill(raw,(byte)0);}}}
  if(seen.size()!=expected.length())throw new IOException("Voice pack is incomplete.");guard.check();byte[] saved=catalog.toString().getBytes(StandardCharsets.UTF_8);try{seal(new File(stage,"catalog.enc"),saved);}finally{Arrays.fill(saved,(byte)0);}File old=active();guard.check();FileOutputStream pointerOut=null;try{pointerOut=pointer.startWrite();pointerOut.write(stage.getName().getBytes(StandardCharsets.UTF_8));pointer.finishWrite(pointerOut);}catch(Exception error){if(pointerOut!=null)pointer.failWrite(pointerOut);throw error;}committed=true;if(old!=null)try{remove(old);}catch(IOException ignored){}return voices.length();
 }finally{if(!committed)remove(stage);}}
 private void remove(File root)throws IOException{String base=root.getCanonicalPath(),parent=files.getCanonicalPath()+File.separator;if(!base.startsWith(parent)||!root.getName().startsWith("personal-pack-"))throw new IOException("Unsafe cleanup path.");deleteChildren(root,base);}
 private void deleteChildren(File f,String base)throws IOException{if(!f.getCanonicalPath().equals(base)&&!f.getCanonicalPath().startsWith(base+File.separator))throw new IOException("Unsafe cleanup member.");if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File child:children)deleteChildren(child,base);}if(f.exists()&&!f.delete())throw new IOException("Voice cleanup could not finish.");}
}
